-- V2.3-r1 role/policy baseline. Apply after the invariant files using a migration administrator.
-- 2026-09-08: full PostGIS execution found the trail policy referenced a different
-- table. Check location_samples timestamps in its own entitlement window.
CREATE ROLE rounds_api NOLOGIN NOSUPERUSER NOBYPASSRLS;
CREATE ROLE rounds_broker NOLOGIN NOSUPERUSER NOBYPASSRLS;
GRANT USAGE ON SCHEMA rounds TO rounds_api, rounds_broker;
CREATE OR REPLACE FUNCTION rounds.context_tenant() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('rounds.tenant_id',true),'')::uuid $$;
CREATE OR REPLACE FUNCTION rounds.context_principal() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('rounds.principal_id',true),'')::uuid $$;
CREATE OR REPLACE FUNCTION rounds.context_city() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('rounds.city_id',true),'')::uuid $$;
CREATE POLICY tenant_scope ON rounds.memberships TO rounds_api USING (tenant_id=rounds.context_tenant()) WITH CHECK (tenant_id=rounds.context_tenant());
GRANT SELECT, INSERT, UPDATE, DELETE ON rounds.memberships TO rounds_api;
