-- 2026-09-08 transaction implementation: same actor may belong to several tenants/cities;
-- receipt access requires the original selected scope, not just actor identity.
CREATE POLICY account_scope ON rounds.command_receipts TO rounds_api USING (actor_id=rounds.context_principal() AND tenant_id IS NOT DISTINCT FROM rounds.context_tenant() AND city_id IS NOT DISTINCT FROM rounds.context_city()) WITH CHECK (actor_id=rounds.context_principal() AND tenant_id IS NOT DISTINCT FROM rounds.context_tenant() AND city_id IS NOT DISTINCT FROM rounds.context_city());
GRANT SELECT, INSERT, UPDATE ON rounds.command_receipts TO rounds_api;
