-- The deployment connection role may SET ROLE rounds_api or rounds_broker only inside reviewed server handlers.
-- Policy alone cannot make an untrusted arbitrary-SQL connection safe; the service controls context and credentials.
CREATE POLICY tenant_scope ON rounds.agreement_revisions TO rounds_api USING(tenant_id=rounds.context_tenant()) WITH CHECK(tenant_id=rounds.context_tenant());
GRANT SELECT, INSERT ON rounds.agreement_revisions TO rounds_api;

-- V2.1: trusted server creates grants; API only reads them.
CREATE ROLE rounds_entitlements NOLOGIN NOSUPERUSER NOBYPASSRLS;
GRANT USAGE ON SCHEMA rounds TO rounds_entitlements;
GRANT SELECT,INSERT,UPDATE,DELETE ON rounds.driver_tracking_grants TO rounds_entitlements;
CREATE POLICY grant_manager ON rounds.driver_tracking_grants TO rounds_entitlements USING(tenant_id=rounds.context_tenant()) WITH CHECK(tenant_id=rounds.context_tenant());
GRANT SELECT ON rounds.driver_tracking_grants TO rounds_api;
CREATE POLICY grant_reader ON rounds.driver_tracking_grants FOR SELECT TO rounds_api USING(tenant_id=rounds.context_tenant());
CREATE POLICY related_driver ON rounds.drivers FOR SELECT TO rounds_api USING(
 EXISTS(SELECT 1 FROM rounds.driver_relationships r WHERE r.tenant_id=rounds.context_tenant() AND r.driver_id=drivers.id AND r.status='active')
 OR EXISTS(SELECT 1 FROM rounds.freelance_agreements f WHERE f.tenant_id=rounds.context_tenant() AND f.driver_id=drivers.id AND f.state IN ('active','disputed')));
CREATE POLICY entitled_position ON rounds.current_positions FOR SELECT TO rounds_api USING(EXISTS(SELECT 1 FROM rounds.driver_tracking_grants g WHERE g.tenant_id=rounds.context_tenant() AND g.driver_id=current_positions.driver_id AND g.tracking_entitlement_id=current_positions.tracking_entitlement_id AND EXISTS(SELECT 1 FROM rounds.tracking_entitlements e WHERE e.id=g.tracking_entitlement_id AND e.tenant_id=g.tenant_id AND e.driver_id=g.driver_id AND e.revoked_at IS NULL AND now()>=e.starts_at AND (e.ends_at IS NULL OR now()<e.ends_at)) AND current_positions.observed_at>=g.starts_at AND current_positions.observed_at<g.ends_at AND g.revoked_at IS NULL AND now()>=g.starts_at AND now()<g.ends_at));
CREATE POLICY entitled_trail ON rounds.location_samples FOR SELECT TO rounds_api USING(EXISTS(SELECT 1 FROM rounds.driver_tracking_grants g WHERE g.tenant_id=rounds.context_tenant() AND g.driver_id=location_samples.driver_id AND g.tracking_entitlement_id=location_samples.tracking_entitlement_id AND EXISTS(SELECT 1 FROM rounds.tracking_entitlements e WHERE e.id=g.tracking_entitlement_id AND e.tenant_id=g.tenant_id AND e.driver_id=g.driver_id AND e.revoked_at IS NULL AND now()>=e.starts_at AND location_samples.observed_at>=e.starts_at AND (e.ends_at IS NULL OR (now()<e.ends_at AND location_samples.observed_at<e.ends_at))) AND g.revoked_at IS NULL AND now()>=g.starts_at AND now()<g.ends_at AND location_samples.observed_at>=g.starts_at AND location_samples.observed_at<g.ends_at));
DROP POLICY tenant_scope ON rounds.notifications;
CREATE POLICY notification_self ON rounds.notifications TO rounds_api USING(tenant_id=rounds.context_tenant() AND principal_id=rounds.context_principal()) WITH CHECK(tenant_id=rounds.context_tenant() AND principal_id=rounds.context_principal());
GRANT SELECT ON rounds.tenants,rounds.vehicle_types TO rounds_api;
CREATE POLICY current_tenant ON rounds.tenants FOR SELECT TO rounds_api USING(id=rounds.context_tenant());
CREATE POLICY vehicle_reference ON rounds.vehicle_types FOR SELECT TO rounds_api USING(rounds.context_principal() IS NOT NULL);
-- Driver principal labels are permitted only through readable driver relationships, not all principals.
CREATE POLICY related_driver_label ON rounds.principals FOR SELECT TO rounds_api USING(EXISTS(SELECT 1 FROM rounds.drivers d WHERE d.principal_id=principals.id));
